
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_gr_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_gr", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([3.944850185045562e+01, 3.879877525453350e+01, 3.790551786875162e+01, 3.670154956521240e+01, 3.512413097358998e+01, 3.313854726701614e+01, 3.077220947759522e+01, 2.813193246928799e+01, 2.527688060029557e+01, 2.138885167363234e+01, 1.221857361477415e+01, 1.485553478689954e+00, 6.181915711891585e-01, 7.886347041943534e-01, 8.371390114530071e-01, 7.849806299218934e-01, 7.132049346760712e-01, 6.489615042422130e-01, 6.035287524476386e-01, 5.743495694408436e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


